#!/usr/bin/env python3
"""Compute ground truth for CSX-309_Q2 from the local CSX-309 package."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Iterable

from PIL import Image, ImageStat


TASK_ID = "CSX-309_Q2"
EVENT_ID = "CSX-309"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_Calbuco_eruption.json",
    "data/remote_sensing/remote_sensing_004_pre.jpg",
    "data/remote_sensing/remote_sensing_005_event.jpg",
    "data/remote_sensing/remote_sensing_002_Sentinel-1_GRD_VV_pre_post_change.json",
    "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json",
    "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json",
]


def load_json(relative_path: str) -> Any:
    with (PACKAGE_DIR / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def round1(value: float) -> float:
    return round(float(value), 1)


def pixel_stream(image: Image.Image) -> Iterable[tuple[int, int, int]]:
    data = image.get_flattened_data() if hasattr(image, "get_flattened_data") else image.getdata()
    for pixel in data:
        if isinstance(pixel, (tuple, list)):
            red, green, blue = pixel[:3]
            yield int(red), int(green), int(blue)
        else:
            value = int(pixel)
            yield value, value, value


def image_metrics(relative_path: str) -> dict[str, float]:
    image = Image.open(PACKAGE_DIR / relative_path).convert("RGB")
    total = 0
    white_neutral = 0

    for red, green, blue in pixel_stream(image):
        total += 1
        channel_range = max(red, green, blue) - min(red, green, blue)
        if red > 180 and green > 180 and blue > 180 and channel_range < 60:
            white_neutral += 1

    means = ImageStat.Stat(image).mean
    rgb_spread = max(means) - min(means)
    return {
        "white_share": round(white_neutral / total, 3),
        "rgb_spread": round1(rgb_spread),
    }


def build_output() -> dict[str, Any]:
    event = load_json("metadata/event.json")
    anchor = load_json("data/event_reports/event_reports_003_Locked_event_anchor_Calbuco_eruption.json")
    radar = load_json("data/remote_sensing/remote_sensing_002_Sentinel-1_GRD_VV_pre_post_change.json")
    s2_index = load_json("data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json")
    rainfall = load_json("data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json")
    pre_image = image_metrics("data/remote_sensing/remote_sensing_004_pre.jpg")
    event_image = image_metrics("data/remote_sensing/remote_sensing_005_event.jpg")

    event_white = event_image["white_share"]
    pre_white = pre_image["white_share"]
    white_ratio = round1(event_white / pre_white)
    s1_mean_change = round1(radar["stats"]["s1_vv_post_minus_pre_db_mean"])
    rain_stats = rainfall["stats"]
    rain_max_mean_ratio = round1(
        rain_stats["gpm_event_precip_mm_max"] / rain_stats["gpm_event_precip_mm_mean"]
    )
    s2_status = s2_index["status"]

    tests = {
        "event_white_ge_0_60": event_white >= 0.60,
        "white_ratio_ge_20": white_ratio >= 20,
        "event_rgb_spread_le_5": event_image["rgb_spread"] <= 5,
        "s2_scene_gap": s2_status == "no_sufficient_scenes",
    }
    conclusion = (
        "obstructed_window_not_surface_map"
        if all(tests.values())
        else "thresholds_not_met"
    )

    metrics = {
        "event_white_share": event_white,
        "pre_white_share": pre_white,
        "white_ratio": white_ratio,
        "event_rgb_spread": event_image["rgb_spread"],
        "s1_mean_change_db": s1_mean_change,
        "rain_max_mean_ratio": rain_max_mean_ratio,
        "s2_status": s2_status,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "numeric_diagnosis",
        "event": {
            "package_id": event["package_id"],
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_window": (
                f"{anchor['temporal_window']['start_date']} to "
                f"{anchor['temporal_window']['end_date']}"
            ),
        },
        "primary_gt": {
            "metrics": metrics,
            "tests": tests,
            "conclusion": conclusion,
            "method_notes": {
                "rounding_order": "Round RGB white shares to three decimals before computing the one-decimal white_ratio; round RGB spread, Sentinel-1 mean change, and rain max/mean ratio to one decimal.",
                "s1_definition": "s1_mean_change_db is the package Sentinel-1 VV post-minus-pre mean-change statistic.",
                "side_product_scope": "Sentinel-1, Sentinel-2, and rainfall values are side metrics for observation-window interpretation, not measured surface damage.",
            },
            "tolerances": {
                "share": 0.002,
                "ratio": 0.1,
                "rgb": 0.1,
                "db": 0.1,
            },
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Return structure",
                    "points": 3,
                    "description": (
                        "Returns the requested JSON structure with the numeric fields, threshold "
                        "object, final label, and one-sentence interpretation."
                    ),
                },
                {
                    "name": "RGB pixel metrics",
                    "points": 5,
                    "description": (
                        "Computes event white share, pre-event white share, and event RGB spread "
                        "using the stated formulas."
                    ),
                },
                {
                    "name": "Derived side metrics",
                    "points": 4,
                    "description": (
                        "Derives the white ratio, Sentinel-1 mean change, and precipitation "
                        "max/mean ratio with the stated definitions and rounding order."
                    ),
                },
                {
                    "name": "Threshold tests",
                    "points": 4,
                    "description": (
                        "Applies all four threshold tests and reports the correct Boolean outcomes."
                    ),
                },
                {
                    "name": "Conclusion wording",
                    "points": 3,
                    "description": (
                        "Gives the final label obstructed_window_not_surface_map and ties it "
                        "directly to the threshold results."
                    ),
                },
                {
                    "name": "Scope control",
                    "points": 1,
                    "description": (
                        "Keeps Sentinel-1, Sentinel-2, and rainfall as side metrics and does not "
                        "turn them into measured surface damage."
                    ),
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    output = build_output()
    with (TASK_DIR / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(output, handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
